const RTL = new Set(['ar', 'he', 'fa']);

let currentLang = 'en';

export function initI18n() {
  const stored = localStorage.getItem('pdftk-lang');
  const browser = (navigator.language || 'en').slice(0, 2);
  const chosen = CATALOG[stored] ? stored : (CATALOG[browser] ? browser : 'en');
  setLang(chosen);
}

export function setLang(code) {
  if (!CATALOG[code]) code = 'en';
  currentLang = code;
  localStorage.setItem('pdftk-lang', code);
  document.documentElement.setAttribute('lang', code);
  document.documentElement.setAttribute('dir', RTL.has(code) ? 'rtl' : 'ltr');
}

export function getLang() { return currentLang; }

export function t(key, params) {
  let s = (CATALOG[currentLang] && CATALOG[currentLang][key]) ?? CATALOG.en[key] ?? key;
  if (params) {
    for (const [k, v] of Object.entries(params)) s = s.replace(`{${k}}`, v);
  }
  return s;
}
